using Ap2Master.Domain;
using Ap2Master.Domain.Entities;

namespace Ap2Master.Content;

public static partial class TeachingFacts
{
    public static IReadOnlyList<TeachingFact> All => TopicCatalog.All.Select(For).ToList();

    public static TeachingFact Synthesize(Topic topic) => For(TopicCatalog.All.First(t => t.Id == topic.Id));

    private static TeachingFact F(
        TopicDef t, string core, string detail, string example, string trap,
        string? formula = null, string? legal = null, bool time = false,
        DateOnly? from = null, DateOnly? until = null,
        DateTime? verified = null, VerificationStatus status = VerificationStatus.Verified,
        string? source = null, string? section = null, string? tech = null)
        => new(t.Id, core, detail, example, trap, formula, legal, time, from, until, verified, status,
            source ?? "NormalizedSyllabus+AmtlicheQuellen", section ?? t.Title, tech);

    public static TeachingFact For(TopicDef t) => t.Id switch
    {
        "t1" => F(t, "Teil 1 prüft das Planen eines Softwareproduktes: Anforderungen, Vorgehen, Planung, Modelle, Architektur und QS.",
            "Typische Operatoren sind Nennen, Beschreiben, Erklären, Vergleichen, Berechnen und Modellieren. Es geht um Lasten/Pflichten, UML/ER, REST, Wirtschaftlichkeit und Projektplanung.",
            "Eine Aufgabe kann verlangen, aus einem Szenario Stakeholder zu klassifizieren, einen Netzplan zu berechnen und ein Klassendiagramm zu ergänzen.",
            "Falle: Teil 1 ist nicht 'nur Theorie ohne Rechnung'. Netzplan und Wirtschaftlichkeit werden gerechnet."),
        "t1-anforderungen" => F(t, "Anforderungsanalyse klärt, WAS das System für welche Stakeholder leisten muss und unter welchen Rahmenbedingungen.",
            "Funktionale Anforderungen beschreiben Verhalten, nicht-funktionale Qualität (Performance, Sicherheit, Usability). Rahmenbedingungen sind oft rechtlich oder technisch vorgegeben.",
            "Helpdesk: 'Ticket zuweisen' ist funktional, 'Antwortzeit < 2 s' ist nicht-funktional, DSGVO ist Rahmenbedingung.",
            "Falle: 'Das System soll modern sein' ist keine prüfbare Anforderung."),
        "t1-stakeholder" => F(t, "Stakeholder sind alle Personen oder Gruppen, die ein Interesse am Projekt haben oder es beeinflussen können.",
            "Man identifiziert sie, bewertet Einfluss und Interesse und leitet Kommunikations- und Einbindungsstrategien ab. Dazu gehören Auftraggeber, Nutzer, Betrieb, Betriebsrat, Datenschutz und Lieferanten.",
            "Im Helpdesk-Projekt: Serviceleitung (Auftraggeber), Agenten (Nutzer), IT-Betrieb, Betriebsrat bei Überwachung, Datenschutzbeauftragte.",
            "Falle: Stakeholder sind nicht nur der zahlende Kunde."),
        "t1-erwartungen" => F(t, "Erwartungen beschreiben gewünschte Ergebnisse, Befürchtungen beschreiben Risiken aus Sicht der Stakeholder.",
            "Beides wird erhoben, um Konflikte früh zu erkennen. Eine Befürchtung kann eine nicht-funktionale Anforderung oder ein Risiko werden.",
            "Agenten erwarten weniger Klicks, befürchten aber Leistungsüberwachung durch Dashboards.",
            "Falle: Befürchtungen einfach zu ignorieren, statt sie in Risiken oder Datenschutzanforderungen zu überführen."),
        "t1-einfluss-interesse" => F(t, "Die Einfluss-/Interesse-Matrix ordnet Stakeholder in vier Felder: eng führen, zufriedenstellen, informieren, beobachten.",
            "Hoher Einfluss + hohes Interesse: eng managen. Hoher Einfluss + niedriges Interesse: zufriedenstellen. Niedriger Einfluss + hohes Interesse: informieren. Sonst beobachten.",
            "Geschäftsführung hat hohen Einfluss, Agenten hohes Interesse. Der Hausmeister wird beobachtet, nicht gesteuert.",
            "Falle: Interesse mit Einfluss verwechseln."),
        "t1-funktionale-anf" => F(t, "Funktionale Anforderungen beschreiben, welche Funktionen das System bereitstellen muss.",
            "Sie sind prüfbar und oft als Use-Cases oder User-Stories formuliert. Sie beantworten WAS, nicht WIE intern implementiert wird.",
            "'Das System erzeugt aus einem Ticket eine E-Mail an den Kunden' ist funktional.",
            "Falle: GUI-Farbe oder Response-Zeit als funktionale Anforderung zu deklarieren."),
        "t1-nfa" => F(t, "Nicht-funktionale Anforderungen beschreiben Qualitätsmerkmale wie Performance, Sicherheit, Wartbarkeit, Usability, Verfügbarkeit.",
            "Sie müssen messbar sein (z. B. 99,5 % Verfügbarkeit/Monat, Passwörter nur als KDF-Hash). ISO 25010 liefert Qualitätsmerkmale.",
            "'Die Suche liefert in 95 % der Fälle in unter 1 s ein Ergebnis.'",
            "Falle: 'schnell und sicher' ohne Maßzahl."),
        "t1-rahmenbedingungen" => F(t, "Rahmenbedingungen begrenzen den Lösungsraum technisch, organisatorisch oder rechtlich.",
            "Beispiele: vorhandenes AD, Cloud-Verbot, DSGVO, Betriebsvereinbarung, Lizenzpolitik, Barrierefreiheit nach BFSG/BITV.",
            "Der Auftraggeber schreibt On-Premises-Betrieb und Microsoft-Stack vor.",
            "Falle: Rahmenbedingungen mit Wunsch-Features zu verwechseln."),
        "t1-lasten-pflichten" => F(t, "Das Lastenheft beschreibt die Anforderungen des Auftraggebers (WAS). Das Pflichtenheft beschreibt die geplante Umsetzung des Auftragnehmers (WIE).",
            "Lastenheft: Ausgangssituation, Ziele, funktionale/nicht-funktionale Anforderungen. Pflichtenheft: Systemspezifikation, Architektur, Abnahmekriterien. Der Auftragnehmer erstellt das Pflichtenheft als Antwort auf das Lastenheft.",
            "Lastenheft: 'Tickets müssen eskaliert werden können.' Pflichtenheft: 'Eskalation nach 4 Stunden an Teamleitung, Status = Eskaliert.'",
            "Falle: Lastenheft und Pflichtenheft als identische Dokumente zu behandeln."),
        "t1-vorgehen" => F(t, "Vorgehensmodelle strukturieren, in welcher Reihenfolge und mit welchen Rückkopplungen Software entsteht.",
            "Klassisch (Wasserfall, V-Modell) plant Phasen vorab. Iterativ-inkrementell (Spirale, Scrum) liefert wiederholt lauffähige Stände. Die Wahl hängt von Stabilität der Anforderungen, Risiko und Kundenverfügbarkeit ab.",
            "Stabile Behördenanforderung → V-Modell. Unklare Produktidee → Scrum oder Prototyping.",
            "Falle: Scrum sei immer besser – ohne Kontext."),
        "t1-wasserfall" => F(t, "Im Wasserfallmodell folgen Phasen sequentiell: Analyse, Entwurf, Implementierung, Test, Betrieb.",
            "Rücksprünge sind teuer. Es eignet sich bei klaren, stabilen Anforderungen und festen Verträgen. Dokumentation ist stark.",
            "Ein gesetzlich spezifiziertes Meldeverfahren mit festem Abgabetermin.",
            "Falle: Wasserfall erlaube beliebiges Zurückspringen ohne Kosten."),
        "t1-v-modell" => F(t, "Das V-Modell stellt jeder Konstruktionsphase eine Teststufe gegenüber: Abnahme zu Analyse, Systemtest zu Entwurf, Integration zu Feinentwurf, Unittest zu Implementierung.",
            "Es betont Verifikation und Validation. In Deutschland ist das V-Modell XT im öffentlichen Bereich bekannt.",
            "Anforderung 'Login' wird später durch den Abnahmetest geprüft, die Klassen durch Unit Tests.",
            "Falle: Die rechte Seite des V als 'nochmal entwickeln' statt als Testhorizont zu lesen."),
        "t1-spiral" => F(t, "Das Spiralmodell nach Boehm wiederholt Zyklen aus Zielbestimmung, Risikoanalyse, Entwicklung und Evaluation.",
            "Risiken steuern den nächsten Prototyp. Es ist aufwendig in der Steuerung, aber gut bei Unsicherheit.",
            "Vor der vollen Entwicklung wird ein Sicherheitsprototyp für die Authentifizierung gebaut.",
            "Falle: Spirale mit Scrum gleichzusetzen. Scrum ist ein Rahmenwerk mit festen Events, Spirale ein risikogetriebenes Modell."),
        "t1-prototyping" => F(t, "Prototyping macht Anforderungen greifbar, indem früh ein bedienbares oder technisches Modell entsteht.",
            "Wegwerfprototyp (explorativ) vs. evolutionärer Prototyp, der zur Grundlage wird. UI-Mockups sind eine Form.",
            "Klickbarer Figma-Prototyp der Ticketmaske zur Abstimmung mit Agenten.",
            "Falle: Den Wegwerfprototyp ungeprüft in Produktion zu übernehmen."),
        "t1-scrum" => F(t, "Scrum ist ein agiles Rahmenwerk mit Sprints, festgelegten Rollen, Events und Artefakten zur empirischen Produktentwicklung.",
            "Transparenz, Überprüfung, Anpassung. Inkremente sollen 'Done' und potenziell lieferbar sein. Scrum ersetzt nicht Fachlichkeit oder Architekturarbeit.",
            "Ein 2-Wochen-Sprint liefert die Ticketliste mit Filter.",
            "Falle: Scrum = kein Plan und keine Dokumentation."),
        "t1-scrum-rollen" => F(t, "Rollen: Product Owner, Scrum Master, Developer. Artefakte: Product Backlog, Sprint Backlog, Increment. Events: Sprint, Planning, Daily, Review, Retro.",
            "PO maximiert Wert und verantwortet das Product Backlog. SM dient dem Team als Coach und beseitigt Hindernisse, ist nicht der Chef. Developer liefern das Increment. Review prüft das Produkt, Retro den Prozess.",
            "Im Review sehen Stakeholder das Filter-Increment; in der Retro wird die Definition of Done geschärft.",
            "Falle: Scrum Master als Projektleiter mit Weisungsrecht."),
        "t1-kanban" => F(t, "Kanban visualisiert den Fluss, begrenzt Work in Progress und steuert über Pull statt fester Sprints.",
            "Typisch: Spalten To Do / Doing / Done, WIP-Limits, Zykluszeit. Kanban ist keine Rollenmethode wie Scrum.",
            "WIP-Limit 3 in 'In Prüfung' verhindert Teststau.",
            "Falle: Kanban als 'Scrum ohne Meetings' zu verkaufen."),
        "t1-devops" => F(t, "DevOps verbindet Entwicklung und Betrieb durch Automatisierung, gemeinsame Verantwortung und schnelles Feedback.",
            "CI/CD, Infrastruktur als Code, Monitoring, kurze Lead Time. Kultur plus Technik, nicht nur ein Tool.",
            "Jeder Merge nach main löst Tests und Deployment in Staging aus.",
            "Falle: DevOps = nur Jenkins installieren."),
        "t1-klassisch-agil" => F(t, "Klassisch plant Scope früh und steuert über Change Requests. Agil hält Zeit und Kosten eher fest und lässt Scope iterativ wachsen.",
            "Klassisch: hohe Vorhersagbarkeit bei bekannten Anforderungen. Agil: hohe Anpassungsfähigkeit. Hybrid kommt in der Praxis häufig vor.",
            "Vertraglich fixierte Behördenschnittstelle klassisch, interne UI agil.",
            "Falle: Agil bedeute, der Kunde könne täglich den Festpreis-Scope folgenlos ändern."),
        "t1-projektplanung" => F(t, "Projektplanung zerlegt Arbeit, terminiert, weist Ressourcen zu und steuert Risiken im magischen Dreieck.",
            "Instrumente: PSP, Netzplan, Gantt, Meilensteine, Schätzung, Make-or-Buy.",
            "Meilenstein M2 'Fachkonzept abgenommen' vor Implementierungsstart.",
            "Falle: Nur ein Gantt ohne Abhängigkeiten als vollständige Planung."),
        "t1-netzplan" => F(t, "Der Vorgangsknotennetzplan modelliert Vorgänge mit Dauer und Anordnungsbeziehungen, meist Ende-Anfang.",
            "Vorwärtsrechnung liefert FAZ/FEZ, Rückwärtsrechnung SAZ/SEZ. Der kritische Pfad hat Gesamtpuffer 0.",
            "A(3) → B(4) und A → C(2) → B ergibt einen kritischen Weg über den längeren Pfad.",
            "Falle: Den längsten Weg mit der Summe aller Dauern ohne Berücksichtigung paralleler Zweige zu verwechseln."),
        "t1-faz-fez-saz-sez" => F(t, "FAZ = frühester Anfangszeitpunkt, FEZ = FAZ + Dauer, SEZ = spätester Endzeitpunkt, SAZ = SEZ − Dauer.",
            "FEZ eines Vorgangs ist der FAZ-Kandidat der Nachfolger (Maximum). SAZ der Nachfolger begrenzt SEZ des Vorgängers (Minimum).",
            "Dauer 5, FAZ 4 → FEZ 9. SEZ 12 → SAZ 7. Gesamtpuffer 3.",
            "Falle: FAZ und SAZ zu vertauschen."),
        "t1-kritischer-pfad" => F(t, "Der kritische Pfad ist die längste Kette von Vorgängen mit Gesamtpuffer 0; er bestimmt die Projektdauer.",
            "Jede Verzögerung dort verschiebt das Projektende. Es kann mehrere kritische Wege geben.",
            "Vorgänge A-D-G mit GP=0 bilden den kritischen Pfad, Dauer 18 Tage.",
            "Falle: 'Kritisch' mit 'wichtig für den Kunden' statt 'ohne Puffer' zu verwechseln."),
        "t1-puffer" => F(t, "Gesamtpuffer GP = SAZ − FAZ = SEZ − FEZ. Freier Puffer FP ist die Zeit, um die ein Vorgang verschoben werden kann, ohne den FAZ der Nachfolger zu gefährden.",
            "GP ≥ FP ≥ 0. FP = min(FAZ der Nachfolger) − FEZ, ohne Nachfolger oft Projektende − FEZ.",
            "FEZ=10, Nachfolger-FAZ=12 → FP=2. SAZ=15 → GP=5.",
            "Falle: GP und FP gleichzusetzen."),
        "t1-gantt" => F(t, "Ein Gantt-Diagramm stellt Vorgänge als Balken über der Zeitachse dar, oft mit Meilensteinen und Abhängigkeiten.",
            "Es eignet sich zur Kommunikation, ersetzt aber nicht die Netzplanrechnung. Kritischer Pfad kann farblich zusätzlich markiert werden, darf aber nicht das einzige Korrektheitsmerkmal sein.",
            "Balken 'Testdaten laden' von Tag 10–12, Meilenstein 'Go-Live' als Raute.",
            "Falle: Überlappende Balken ohne Anordnungsbeziehungen als Netzplan zu lesen."),
        "t1-meilensteine" => F(t, "Meilensteine sind ereignisbezogene Kontrollpunkte mit Dauer 0, an denen ein klarer Zustand erreicht sein muss.",
            "Sie dienen Steuerung und Vertrag (Zahlungsmeilensteine). Formulierung als erreichter Zustand, nicht als Tätigkeit.",
            "'Lastenheft abgenommen' statt 'Lastenheft schreiben'.",
            "Falle: Meilensteine mit Vorgängen positiver Dauer zu verwechseln."),
        "t1-magisches-dreieck" => F(t, "Das magische Dreieck verbindet Leistung (Scope/Qualität), Zeit und Kosten; eine Größe ändert die anderen.",
            "Qualität wird oft als vierte Größe oder Teil der Leistung modelliert. Zielkonflikte müssen transparent entschieden werden.",
            "Zwei Wochen früher liefern bedeutet Scope reduzieren oder Kosten (mehr Personal) erhöhen.",
            "Falle: Alle drei Größen gleichzeitig maximal ohne Zielkonflikt fordern."),
        "t1-risiko" => F(t, "Risikoanalyse identifiziert, bewertet (Eintrittswahrscheinlichkeit × Schadensausmaß) und steuert Risiken (vermeiden, vermindern, überwälzen, akzeptieren).",
            "Chancen können analog betrachtet werden. Restrisiko bleibt bewusst.",
            "Ausfall der Schlüsselperson: Wahrscheinlichkeit mittel, Schaden hoch → Pairing und Dokumentation.",
            "Falle: Nur technische Risiken betrachten und rechtliche/personelle ignorieren."),
        "t1-schaetzung" => F(t, "Schätzverfahren machen Aufwand vergleichbar: Expertenschätzung, Analogie, Drei-Punkt (PERT), Story Points, Planning Poker, Function Points.",
            "PERT: (opt + 4×real + pess) / 6. Schätzung ist keine Zusage. Buffer und Unsicherheit gehören dazu.",
            "opt=4, real=6, pess=14 → (4+24+14)/6 = 7 Tage.",
            "Falle: Story Points mit Stunden gleichzusetzen."),
        "t1-make-or-buy" => F(t, "Make-or-Buy entscheidet, ob eine Leistung selbst erstellt oder beschafft wird.",
            "Kriterien: Kernkompetenz, Kosten, Zeit, Lizenz, Abhängigkeit, Qualität, Datenschutz. TCO statt nur Kaufpreis.",
            "Authentifizierung über bewährten Identity-Provider kaufen, Fachlogik Helpdesk selbst bauen.",
            "Falle: Nur den Anschaffungspreis ohne Betrieb, Schulung und Exit-Kosten zu vergleichen."),
        "t1-wirtschaft" => F(t, "Wirtschaftlichkeitsrechnungen bewerten, ob sich ein Vorhaben lohnt: Wirtschaftlichkeit, Rentabilität, ROI, Amortisation, Kapitalwert.",
            "Formeln müssen unterscheidbar bleiben. Einheiten und Zeitraum angeben.",
            "Ein Helpdesk-Projekt mit 80.000 € Ertrag und 50.000 € Aufwand.",
            "Falle: Wirtschaftlichkeit mit Rentabilität zu verwechseln."),
        "t1-wirtschaftlichkeit" => F(t, "Wirtschaftlichkeit = Ertrag / Aufwand. Werte > 1 bedeuten, der Ertrag übersteigt den Aufwand.",
            "Ertrag und Aufwand müssen demselben Zeitraum und derselben Abgrenzung folgen. Nicht mit Produktivität (Mengen) oder Rentabilität (Gewinn/Kapital) verwechseln.",
            "Ertrag 80.000 €, Aufwand 50.000 € → 1,6.",
            "Falle: Wirtschaftlichkeit = Gewinn / Kapital oder Ertrag − Aufwand.",
            "Ertrag / Aufwand"),
        "t1-roi" => F(t, "ROI (Return on Investment) = Gewinn / eingesetztes Kapital × 100 (in Prozent).",
            "Varianten existieren (z. B. mit Umsatz), in der Prüfung die gegebene Definition nutzen. Zeitraum angeben.",
            "Gewinn 12.000 €, Einsatz 60.000 € → 20 %.",
            "Falle: ROI mit Wirtschaftlichkeit (Ertrag/Aufwand) gleichzusetzen.",
            "Gewinn / eingesetztes Kapital × 100"),
        "t1-rentabilitaet" => F(t, "Rentabilität = Gewinn / eingesetztes Kapital × 100.",
            "Sie misst die Verzinsung des Kapitals. Eigenkapitalrentabilität nutzt EK, Gesamtkapitalrentabilität das Gesamtkapital.",
            "Gewinn 15.000 €, Kapital 100.000 € → 15 %.",
            "Falle: Rentabilität = Ertrag / Aufwand.",
            "Gewinn / eingesetztes Kapital × 100"),
        "t1-amortisation" => F(t, "Amortisationsdauer = Anschaffungsauszahlung / durchschnittlicher jährlicher Rückfluss (Cashflow).",
            "Je kürzer, desto schneller fließt das Kapital zurück. Qualitative Nutzen (Image) fehlen in der statischen Amortisation.",
            "Investition 40.000 €, Rückfluss 10.000 €/Jahr → 4 Jahre.",
            "Falle: Gewinn statt Cashflow einzusetzen, wenn die Aufgabe explizit Rückfluss verlangt.",
            "Anschaffung / jährlicher Rückfluss"),
        "t1-npv" => F(t, "Kapitalwert (NPV) ist die Summe der diskontierten Cashflows: Σ CFt / (1+i)^t. Positiver Kapitalwert bedeutet Vorteilhaftigkeit bei gegebenem Kalkulationszins.",
            "t=0 enthält meist die Investition als negativer Cashflow. Dynamisches Verfahren, berücksichtigt Zeitwert des Geldes.",
            "−10.000 + 6.000/1,1 + 6.000/1,1² ≈ +416 €.",
            "Falle: Cashflows undiskontiert zu addieren und das als Kapitalwert zu bezeichnen.",
            "Σ CFt / (1+i)^t"),
        _ => MoreTeil1(t)
    };

    private static TeachingFact MoreTeil1(TopicDef t) => t.Id switch
    {
        "t1-uml-klasse" => F(t, "Ein Klassendiagramm zeigt Typen mit Attributen, Operationen und Beziehungen (Assoziation, Aggregation, Komposition, Generalisierung).",
            "Klassenname oben, Attribute, Methoden. Sichtbarkeit: + public, - private, # protected, ~ package. Unterstrichen = statisch. Kursiv = abstrakt.",
            "Klasse Ticket mit -id:int, +eskalieren():void, assoziiert zu Kunde 0..* : 1.",
            "Falle: Objekte statt Typen oder Datenbanktabellen 1:1 als Klassen ohne Verhalten zu zeichnen."),
        "t1-uml-attribute" => F(t, "Attributsyntax: Sichtbarkeit name: Typ [Multiplizität] = Default. Methodensignatur: Sichtbarkeit name(param:Typ):Rückgabe.",
            "Reihenfolge und Typen sind prüfungsrelevant. Getter/Setter nur wenn fachlich verlangt.",
            "+titel: String, +setzeStatus(status: Status): void",
            "Falle: Java-Getter als einzig erlaubte Form in UML zu verlangen – UML ist sprachunabhängig."),
        "t1-uml-sichtbarkeit" => F(t, "+ public, − private, # protected, ~ package/implementation.",
            "Private Attribute mit öffentlichen Operationen entsprechen Kapselung. Protected für Vererbungshierarchien.",
            "−passwortHash: String ist privat, +anmelden(...): bool öffentlich.",
            "Falle: # als private zu lesen."),
        "t1-uml-multi" => F(t, "Multiplizitäten stehen an den Enden der Beziehung: 1, 0..1, 0..*, 1..*, n, a..b.",
            "Gelesen als 'ein Ticket gehört zu genau einem Kunden; ein Kunde hat 0..* Tickets'. Die Zahl steht beim gegenüberliegenden Ende der betrachteten Klasse – Prüfungstexte genau lesen.",
            "Kunde 1 —— 0..* Ticket",
            "Falle: Die Multiplizität an das falsche Ende zu schreiben."),
        "t1-uml-assoziation" => F(t, "Eine Assoziation ist eine strukturelle Beziehung zwischen Klassen, oft mit Rollen und Multiplizitäten.",
            "Navigationspfeile optional. Attribut vs. Assoziation: komplexe Typen meist als Assoziation.",
            "Ticket — Bearbeiter (Mitarbeiter)",
            "Falle: Jede Benutzung einer Klasse in einer Methode als Assoziation zu zeichnen (das wäre Abhängigkeit)."),
        "t1-uml-aggregation" => F(t, "Aggregation (leere Raute) modelliert eine Kann-Ganzes-Teil-Beziehung ohne existenzielle Abhängigkeit.",
            "Das Teil kann ohne das Ganze existieren. Raute steht am Ganzen.",
            "Abteilung ◇—— Mitarbeiter (Mitarbeiter existiert auch ohne Abteilung).",
            "Falle: Aggregation und Komposition zu vertauschen."),
        "t1-uml-komposition" => F(t, "Komposition (gefüllte Raute) ist eine existenzielle Ganzes-Teil-Beziehung: Teile werden mit dem Ganzen gelöscht und gehören zu höchstens einem Ganzen.",
            "Multiplizität am Ganzen ist 1 oder 0..1, nicht *.",
            "Rechnung ◆—— 1..* Rechnungsposition",
            "Falle: n:m als Komposition zu modellieren."),
        "t1-uml-vererbung" => F(t, "Generalisierung: ungefülltes Dreieck zeigt auf die Superklasse. Subklassen erben Attribute und Operationen und dürfen spezialisieren.",
            "Ist-ein-Beziehung. Abstrakte Klassen kursiv. Mehrfachvererbung in UML möglich, in vielen Sprachen nicht.",
            "Ticket ← BugTicket, ChangeTicket",
            "Falle: Den Pfeil zur Subklasse zu zeichnen."),
        "t1-uml-usecase" => F(t, "Use-Case-Diagramme zeigen Akteure, Anwendungsfälle und Systemgrenzen sowie include, extend und Generalisierung.",
            "Ein Use Case liefert einem Akteur einen beobachtbaren Nutzen. Keine GUI-Buttons als Use Cases.",
            "Akteur Agent — Use Case 'Ticket schließen', System Helpdesk.",
            "Falle: 'Datenbank speichern' als Use Case."),
        "t1-uml-akteure" => F(t, "Akteure sind Rollen außerhalb des Systems: Nutzer, Fremdsysteme, Zeit. Stickman oder Rechteck «actor».",
            "Primärakteur löst den Fall aus, Sekundärakteur wird eingebunden (z. B. Mailserver).",
            "Kunde (primär) startet 'Ticket erfassen', SMTP-Gateway ist sekundär.",
            "Falle: Interne Klassen als Akteure."),
        "t1-uml-include-extend" => F(t, "«include» ist zwingende Einbindung (Basis → included). «extend» ist optionale Erweiterung (Extension → Basis) mit Extension Point.",
            "Include-Pfeil zum included Use Case. Extend-Pfeil zum Basis-Use-Case.",
            "'Ticket speichern' include 'Protokoll schreiben'. 'Spam prüfen' extend 'Ticket erfassen'.",
            "Falle: Die Pfeilrichtung von include/extend zu vertauschen."),
        "t1-uml-akteur-gen" => F(t, "Akteurgeneralisierung: Spezieller Akteur erbt Use Cases des allgemeinen, z. B. Teamleiter → Agent.",
            "Der Spezialakteur kann zusätzliche Use Cases haben.",
            "Teamleiter erbt 'Ticket bearbeiten' und hat zusätzlich 'Bericht exportieren'.",
            "Falle: Generalisierung als include zu zeichnen."),
        "t1-uml-aktivitaet" => F(t, "Aktivitätsdiagramme modellieren Abläufe mit Aktionen, Kontrollflüssen, Entscheidungen, Parallelität und Objektflüssen.",
            "Startknoten (gefüllt), Endknoten, Aktionsrechtecke, Rauten, Balken für Fork/Join.",
            "Ticket anlegen → priorisieren → zuweisen → bearbeiten → schließen.",
            "Falle: Ein Aktivitätsdiagramm als Klassendiagramm mit Methodenliste zu missbrauchen."),
        "t1-uml-swimlanes" => F(t, "Swimlanes / Partitionen ordnen Aktionen Verantwortlichen (Rollen, Systeme) zu.",
            "Vertikale oder horizontale Bahnen. Sie ersetzen keine Datenflüsse vollständig.",
            "Bahnen Agent, System, Kunde.",
            "Falle: Dieselbe Aktion in zwei Bahnen ohne klare Verantwortung."),
        "t1-uml-entscheidungen" => F(t, "Entscheidungsknoten (Raute) verzweigen; zusammenführende Rauten bündeln alternative Pfade.",
            "Genau ein Ausgang trifft zu (XOR), Guards dürfen sich nicht überlappen und sollten vollständig sein.",
            "[Priorität = hoch] vs. [sonst]",
            "Falle: Fehlender else/sonst-Zweig bei unvollständiger Fallunterscheidung."),
        "t1-uml-guards-act" => F(t, "Guards sind Bedingungen in eckigen Klammern an Kontrollflüssen, z. B. [Tickets > 0].",
            "Sie müssen disjunkt und möglichst vollständig sein. [else] ist üblich.",
            "[ SLA verletzt ] / [ SLA eingehalten ]",
            "Falle: Guards weglassen, sodass unklar ist, welcher Zweig gilt."),
        "t1-uml-fork-join" => F(t, "Fork spaltet parallele Abläufe, Join wartet, bis alle eingehenden Zweige angekommen sind. Dargestellt als Synchronisationsbalken.",
            "Fork hat einen Eingang und mehrere Ausgänge, Join umgekehrt. Nicht mit Entscheidung (XOR) verwechseln.",
            "Nach 'Freigabe' parallel 'Mail senden' und 'Statistik aktualisieren', dann Join.",
            "Falle: Fork als XOR-Entscheidung zu verwenden."),
        "t1-uml-sequenz" => F(t, "Sequenzdiagramme zeigen den Nachrichtenaustausch entlang von Lebenslinien in der Zeit (oben nach unten).",
            "Nachrichten: synchron (gefüllte Pfeilspitze), asynchron (offene), Rückgabe gestrichelt. Fragmente alt/opt/loop.",
            "Agent → UI: speichern(); UI → API: POST /tickets; API → DB: INSERT.",
            "Falle: Klassenbeziehungen statt Nachrichten zu zeichnen."),
        "t1-uml-lebenslinien" => F(t, "Eine Lebenslinie repräsentiert ein Objekt oder eine Rolle: Name:Typ. Zerstörung mit X am Ende.",
            "Akteure können links stehen. Create als gestrichelte Nachricht auf die Kopfbox.",
            "t: TicketService",
            "Falle: Eine Klasse mehrfach ohne klare Instanzen zu verwirren, wenn die Aufgabe Instanzen verlangt."),
        "t1-uml-aktivierung" => F(t, "Aktivierungsbalken zeigen, wann eine Lebenslinie die Kontrolle hat.",
            "Bei synchronem Aufruf bleibt der Aufrufer aktiv, bis die Rückgabe kommt (oder gestapelte Balken).",
            "Balken auf TicketService während create().",
            "Falle: Aktivierung mit Zustand im Zustandsdiagramm zu verwechseln."),
        "t1-uml-sync-async" => F(t, "Synchron: Aufrufer wartet (gefüllte Dreiecksspitze). Asynchron: Aufrufer wartet nicht (offene Spitze).",
            "UI-Thread sollte lange Operationen asynchron anstoßen. Callbacks/Events sind typisch asynchron.",
            "sync getTicket(id), async notify(listener).",
            "Falle: Asynchron mit Rückgabepfeil zu kombinieren, als würde synchron gewartet."),
        "t1-uml-return" => F(t, "Rückgabenachrichten sind gestrichelt, oft mit Rückgabewert. Bei offensichtlich synchronen Aufrufen dürfen sie weggelassen werden, wenn die Aufgabe es erlaubt.",
            "Offene Pfeilspitze, gestrichelte Linie zurück zum Aufrufer.",
            "ticket ← create()",
            "Falle: Rückgabe als durchgezogenen synchronen Aufruf in die Gegenrichtung."),
        "t1-uml-fragmente" => F(t, "Combined Fragments: alt (if/else), opt (if ohne else), loop (Wiederholung) mit Guards in [ ].",
            "Operandentrennung bei alt durch gestrichelte horizontale Linie. par für Parallelität, break zum Abbruch.",
            "alt [gefunden] zeige Ticket  [else] 404",
            "Falle: loop ohne Guard oder Abbruchbedingung."),
        "t1-uml-zustand" => F(t, "Zustandsdiagramme modellieren Lebenszyklus eines Objekts: Zustände, Ereignisse, Transitionen, Guards, Aktivitäten.",
            "Gefüllter Start, Endzustand mit Kreis. Internes Verhalten: entry / exit / do.",
            "Ticket: Neu → InArbeit → Geschlossen.",
            "Falle: Aktivitätsablauf (Prozess) als Objektlebenszyklus auszugeben, ohne Objektbezug."),
        "t1-uml-zustaende" => F(t, "Ein Zustand ist eine Zeitspanne, in der das Objekt eine bestimmte Bedingung erfüllt und auf Ereignisse wartet.",
            "Zusammengesetzte Zustände können Unterzustände haben. Start ist Pseudozustand.",
            "InArbeit mit do / bearbeiten",
            "Falle: 'Speichern' als Zustand statt als Transition/Aktion."),
        "t1-uml-ereignisse" => F(t, "Ereignisse lösen Transitionen aus: Signal, Call, Zeit (after/at), Change (when).",
            "Syntax: event [guard] / /aktion",
            "eskalieren [alter > 4h] / benachrichtige(leitung)",
            "Falle: Ereignis und Aktion zu vertauschen."),
        "t1-uml-transitionen" => F(t, "Eine Transition verbindet zwei Zustände und wird durch ein Ereignis ausgelöst, sofern der Guard wahr ist.",
            "Selbsttransition bleibt im Zustand, führt aber exit/entry je nach Modellierung aus – in Prüfungen oft als interne Transition versus Selbsttransition unterscheiden.",
            "InArbeit → Geschlossen bei Ereignis schließen",
            "Falle: Transition ohne erlaubtes Ereignis, sodass der Zustand nie verlassen werden kann, obwohl die Aufgabe das verlangt."),
        "t1-uml-guards-state" => F(t, "Guards an Transitionen müssen wahr sein, sonst findet der Wechsel nicht statt.",
            "Mehrere Transitionen desselben Ereignisses brauchen disjunkte Guards.",
            "[prio = hoch] vs. [prio = niedrig]",
            "Falle: Überlappende Guards, die denselben Fall zweimal erlauben."),
        "t1-uml-entry-exit-do" => F(t, "entry / Aktion beim Betreten, exit / beim Verlassen, do / laufende Aktivität im Zustand.",
            "do kann durch Ereignis unterbrochen werden. entry läuft auch bei Selbsttransition, interne Transition umgeht entry/exit.",
            "entry / zeitstempelSetzen; do / timer; exit / timerStoppen",
            "Falle: do mit einmaliger entry-Aktion zu verwechseln."),
        "t1-er" => F(t, "Ein ER-Modell beschreibt Entitätstypen, Attribute und Beziehungen unabhängig von einem konkreten DBMS.",
            "Ziel ist konzeptionelle Modellierung. Danach Ableitung in Relationen mit PK/FK.",
            "Kunde 1 — n Ticket, Ticket n — m Kategorie über TicketKategorie.",
            "Falle: n:m ohne Auflösung direkt als eine Tabelle mit zwei FKs ohne Beziehungstyp, wenn die Aufgabe die Auflösung verlangt."),
        "t1-er-entitaeten" => F(t, "Entitätstypen sind unterscheidbare Dinge der Wirklichkeit; Attribute beschreiben sie. Schlüsselattribute identifizieren.",
            "Schwache Entitäten sind vom Eigentümer abhängig. Mehrwertige Attribute später normalisieren.",
            "Kunde(Kundennr, Name, Ort)",
            "Falle: 'Alter' und 'Geburtsdatum' unkommentiert parallel, obwohl eines ableitbar ist – je nach Aufgabenstellung."),
        "t1-er-pk-fk" => F(t, "Der Primärschlüssel identifiziert eindeutig und ist minimal. Fremdschlüssel referenzieren den PK (oder Unique) einer anderen Relation.",
            "FK-Werte müssen existieren oder NULL sein, wenn erlaubt. Surrogate Keys (Id) vs. natürliche Schlüssel.",
            "Ticket.KundenId → Kunde.Id",
            "Falle: Den FK in die 1-Seite einer 1:n zu legen (er gehört in die n-Seite)."),
        "t1-er-kardinalitaeten" => F(t, "Kardinalitäten beschreiben, wie viele Instanzen teilnehmen: 1:1, 1:n, n:m; min..max (1, 0..1, 0..*, 1..*).",
            "Look-across vs. Look-here hängt von der Notation ab. In Prüfungen die gegebene Notation verwenden.",
            "Ein Kunde hat viele Tickets, ein Ticket genau einen Kunden: 1:n.",
            "Falle: 1:n und n:1 begrifflich zu verdrehen, ohne die Leserichtung zu prüfen."),
        "t1-er-chen-crowsfoot" => F(t, "Chen: Rechtecke Entitäten, Rauten Beziehungen, Ovale Attribute. Crow's Foot: Linienenden als Krähenfuß (*), Strich (1), Kreis (0).",
            "Beide können dieselbe Min-Max-Semantik ausdrücken. Nicht mischen ohne Legende.",
            "Krähenfuß an Ticket zur Kundenbeziehung bedeutet 'viele Tickets'.",
            "Falle: Chen-Raute mit UML-Klasse zu verwechseln."),
        "t1-er-ableitung" => F(t, "Ableitung: Jeder Entitätstyp → Relation. 1:n → FK auf der n-Seite. 1:1 → FK auf der optionalen Seite. n:m → Beziehungsrelation mit zwei FKs als PK.",
            "Attribute der Beziehung wandern in die Beziehungsrelation. Mehrwertige Attribute eigene Tabelle.",
            "TicketKategorie(TicketId, KategorieId) als PK(TicketId, KategorieId).",
            "Falle: n:m durch zwei FKs in einer der beiden Haupttabellen aufzulösen."),
        "t1-db-architektur" => F(t, "Datenbankarchitektur unterscheidet externe Sichten, konzeptionelles Schema und internes Schema (ANSI-SPARC) sowie Client, DBMS-Server und Speicher.",
            "Drei-Ebenen-Architektur entkoppelt Anwendungen von physischer Speicherung.",
            "View vOffeneTickets als externe Sicht auf Tabelle Ticket.",
            "Falle: 'Die Anwendung ist die Datenbank' – Vermischung von Präsentation und Speicherung."),
        "t1-db-constraints" => F(t, "Constraints sichern Integrität: PRIMARY KEY, FOREIGN KEY, UNIQUE, NOT NULL, CHECK, DEFAULT.",
            "Referentielle Aktionen: ON DELETE CASCADE/SET NULL/RESTRICT. Checks gehören zur Tabelle, Geschäftsregeln manchmal in die Anwendung – Prüfung: beide nennen.",
            "CHECK (Prioritaet BETWEEN 1 AND 5)",
            "Falle: UNIQUE und PRIMARY KEY gleichzusetzen (PK impliziert UNIQUE+NOT NULL, Tabelle hat nur einen PK)."),
        "t1-rest" => F(t, "REST stilisiert Ressourcen über URIs, repräsentationsorientiert (oft JSON), zustandslos, mit einheitlichen HTTP-Methoden.",
            "Ressourcen, Repräsentationen, Hypermedia optional (HATEOAS). Nicht jede HTTP-API ist REST.",
            "GET /tickets/12 liefert Ticket 12 als JSON.",
            "Falle: REST mit SOAP oder mit 'JSON über POST /getTickets' ohne Ressourcenmodell gleichzusetzen."),
        "t1-http-methoden" => F(t, "GET lesen (sicher, idempotent), POST erzeugen/nicht idempotent, PUT vollständiges Aktualisieren (idempotent), PATCH teilweise, DELETE löschen (idempotent).",
            "Sicher = keine Zustandsänderung. Idempotent = wiederholte gleiche Anfrage gleicher Effekt.",
            "PUT /tickets/12 mit Gesamtdarstellung überschreibt Ticket 12.",
            "Falle: GET mit Side-Effects (Löschen per GET-Link)."),
        "t1-crud" => F(t, "CRUD: Create→POST, Read→GET, Update→PUT/PATCH, Delete→DELETE.",
            "Listenressource /tickets, Item /tickets/{id}. POST auf Collection erzeugt, Location-Header mit neuer URI.",
            "POST /tickets → 201 Created, Location: /tickets/88",
            "Falle: POST /updateTicket als REST-gerecht zu bezeichnen."),
        "t1-statuscodes" => F(t, "2xx Erfolg (200 OK, 201 Created, 204 No Content), 4xx Client (400, 401, 403, 404, 409, 422), 5xx Server (500, 503).",
            "401 unauthenticated, 403 authenticated aber nicht berechtigt. 404 nicht gefunden. 409 Konflikt.",
            "GET unbekannte Id → 404; fehlendes Token → 401; User darf fremdes Ticket nicht sehen → 403.",
            "Falle: 401 und 403 zu vertauschen."),
        "t1-header" => F(t, "Header transportieren Metadaten: Authorization, Content-Type, Accept, Location, ETag, Cache-Control, Correlation-Id.",
            "Content-Type beschreibt den Body, Accept die gewünschte Antwort.",
            "Content-Type: application/json",
            "Falle: Fachdaten nur in selbst erfundenen Headern statt im Body, wenn die API JSON-Ressourcen spezifiziert."),
        "t1-json" => F(t, "JSON kennt Objekt, Array, String, Zahl, Boolean, null. Schlüssel in Objekten sind Strings.",
            "Kein Kommentar im Standard. Datumsangaben üblich als ISO-8601-Strings. Zahlen ohne führende Nullen.",
            "{\"id\":12,\"status\":\"offen\",\"tags\":[\"prio\"]}",
            "Falle: Trailing Comma oder einfache Quotes als gültiges JSON."),
        "t1-uri" => F(t, "URI-Design: Substantive im Plural, Hierarchie /tickets/12/kommentare, Filter als Query ?status=offen, keine Verben in Pfaden.",
            "IDs pfadseitig, optionale Filter queryside. Versionierung /v1/ bewusst und stabil.",
            "/tickets?status=offen&sort=erstelltAm",
            "Falle: /getAllTickets.php als REST-URI."),
        "t1-idempotenz" => F(t, "Eine Operation ist idempotent, wenn mehrfaches Ausführen denselben Ressourcenzustand hinterlässt wie einmaliges.",
            "GET, PUT, DELETE sind idempotent, POST in der Regel nicht. PATCH kann, muss aber nicht.",
            "DELETE /tickets/12 zweimal: zweites Mal oft 404, Zustand 'nicht vorhanden' bleibt.",
            "Falle: Idempotenz mit Sicherheit (safe) zu verwechseln. DELETE ist idempotent, aber nicht safe."),
        "t1-uiux" => F(t, "UI betrifft Oberfläche, UX das gesamte Nutzungserlebnis inklusive Erwartungen, Fehler, Feedback und Barrierefreiheit.",
            "Nielsen-Heuristiken, Konsistenz, Sichtbarkeit des Systemstatus, Fehlervermeidung.",
            "Nach Speichern erscheint 'Ticket 12 gespeichert' plus Undo, nicht nur ein Farbwechsel.",
            "Falle: UX auf 'hübsch' zu reduzieren und Farbe als einziges Statussignal zu nutzen."),
        "t1-mockups" => F(t, "Mockups sind statische oder klickbare Entwürfe der Oberfläche zur Abstimmung, bevor teuer entwickelt wird.",
            "Wireframe (struktur), Mockup (visuell), Prototyp (interaktiv). Sie sind keine Abnahme des Codes.",
            "Papier-Wireframe der Ticketliste mit Filterzeile.",
            "Falle: Das Mockup 1:1 als implementierte Barrierefreiheit zu werten, ohne Tastatur und Kontrast zu prüfen."),
        "t1-accessibility" => F(t, "Barrierefreiheit ermöglicht Nutzung ohne und mit Einschränkungen: Tastaturbedienung, Kontrast, Semantik, Screenreader, Untertitel, nicht Farbe als einziges Signal.",
            "BITV/BFSG und WCAG (A/AA/AAA). Fokus sichtbar, Labels verknüpft, Alternativtexte.",
            "Pflichtfeldfehler als Icon plus Text 'Datum fehlt', nicht nur roter Rahmen.",
            "Falle: 'Wir haben ein hohes Kontrastthema, also ist die App barrierefrei.'"),
        "t1-heuristiken" => F(t, "Nielsens Heuristiken u. a.: Systemstatus sichtbar, Übereinstimmung mit der realen Welt, Kontrolle/Freiheit, Konsistenz, Fehlervermeidung, Wiedererkennen statt Erinnern, Flexibilität, minimalistisches Design, Fehlermanagement, Hilfe.",
            "Sie sind Faustregeln, keine automatische Note.",
            "Undo nach versehentlichem Löschen erfüllt Nutzerkontrolle.",
            "Falle: Heuristik-Review mit Benutzertest vollständig zu ersetzen."),
        "t1-dsgvo" => F(t, "Die DSGVO schützt personenbezogene Daten in der EU: Rechtmäßigkeit, Treu und Glauben, Transparenz, Zweckbindung, Minimierung, Richtigkeit, Speicherbegrenzung, Integrität/Vertraulichkeit, Rechenschaft.",
            "Rechtsgrundlagen Art. 6: Einwilligung, Vertrag, rechtliche Pflicht, lebenswichtige Interessen, öffentliches Interesse, berechtigte Interessen. Betroffenenrechte Art. 12–22.",
            "Ticket enthält Name und E-Mail → personenbezogen, Löschkonzept und Zugriffskonzept nötig.",
            "Falle: 'In der Cloud gilt die DSGVO nicht' oder 'anonym, weil nur die Personalnummer da steht' (kann identifizierbar sein)."),
        "t1-datensparsamkeit" => F(t, "Datenminimierung: nur personenbezogene Daten, die für den Zweck erforderlich sind.",
            "Keine Vorratsspeicher von Geburtsdatum, wenn Alter nicht benötigt wird. Anonymisierung vs. Pseudonymisierung unterscheiden.",
            "Für SLA-Statistik Ticket-Id und Zeiten, nicht der Mailtext.",
            "Falle: 'Wir speichern alles, man könnte es brauchen.'"),
        "t1-einwilligung" => F(t, "Einwilligung muss informiert, freiwillig, eindeutig und widerrufbar sein (Art. 7). Kopplungsverbot beachten.",
            "Nicht die einzige Rechtsgrundlage. Vertragserfüllung kann Login-Daten tragen, Newsletter braucht meist Einwilligung.",
            "Opt-in-Checkbox ungesetzt für Marketing, nicht vorausgefüllt.",
            "Falle: Vorangekreuzte Boxen als wirksame Einwilligung."),
        "t1-loeschung" => F(t, "Löschkonzepte definieren Fristen, Verantwortliche, technische Umsetzung und Ausnahmen (Aufbewahrungspflichten, Verteidigung von Rechtsansprüchen).",
            "Recht auf Löschung Art. 17 mit Ausnahmen. Sperrung statt Löschung, wenn Aufbewahrungspflicht.",
            "Tickets 3 Jahre nach Schluss, Bewerbungsdaten 6 Monate, Buchungsbelege länger.",
            "Falle: 'Löschen = nur in der GUI ausblenden, Datensatz bleibt ewig.'"),
        "t1-passwort-anf" => F(t, "Passwörter werden nicht im Klartext und nicht mit unsicherem Schnellhash allein gespeichert, sondern mit Passwort-KDF (z. B. Argon2, scrypt, bcrypt) plus Salt.",
            "Pepper optional serverseitig. Übertrag nur über TLS. Keine eigenen 'Verschlüsselungen' mit SHA-1 ohne KDF.",
            "salt || Argon2(password, salt, params)",
            "Falle: SHA-256(password) ohne Salt/KDF als Stand der Technik."),
        "t1-security-anf" => F(t, "Sicherheitsanforderungen betreffen Vertraulichkeit, Integrität, Authentizität, Verfügbarkeit, Last, Protokollierung, Berechtigungen (least privilege).",
            "Sie gehören ins Lastenheft als NFA und in die Architektur (AuthN/AuthZ, TLS, Secrets-Handling).",
            "Sitzung nach 15 min Inaktivität, Rollen Agent/Leitung, Audit-Log ohne Passwörter.",
            "Falle: Sicherheit nur als Firewall-Thema ohne Anwendungsrechte."),
        "t1-architektur" => F(t, "Softwarearchitektur legt Strukturen, Schnittstellen und Qualitätsziele fest: Schichten, Verteilung, Modularisierung, Muster.",
            "Entscheidungen sind trade-offs. Qualitätsszenarien begründen die Wahl.",
            "Drei-Schichten, REST-API, SQLite lokal vs. Server-DB.",
            "Falle: Architektur = Klassendiagramm ohne Qualitätsziele."),
        "t1-monolith" => F(t, "Ein Monolith ist eine zusammen ausgelieferte Anwendungseinheit. Modularer Monolith intern zerlegbar, ohne verteilte Laufzeit.",
            "Vorteil: einfachere Transaktionen und Debugging. Nachteil: Skalierung und Teamgrenzen.",
            "Eine Helpdesk-WAR/EXE mit UI, Logik, Datenzugriff.",
            "Falle: Monolith automatisch mit 'schlechtem Code' gleichzusetzen."),
        "t1-client-server" => F(t, "Client-Server: Clients fordern Dienste an, Server stellen sie bereit und halten oft die Datenhoheit.",
            "Fat/Thin Client. Zustand kann serverseitig oder in Tokens liegen.",
            "WPF-Client spricht REST-Server an, der die Datenbank besitzt.",
            "Falle: Peer-to-Peer mit Client-Server zu verwechseln."),
        "t1-drei-schichten" => F(t, "Präsentation, Fachlogik (Application/Domain), Datenhaltung. Abhängigkeiten zeigen nach innen/unten, nicht umgekehrt.",
            "Ermöglicht UI-Tausch und Tesbarkeit. Nicht jede physische Verteilung entspricht drei Schichten.",
            "WPF-View → Services → EF Core/SQLite.",
            "Falle: SQL aus dem Code-Behind der View als Drei-Schichten zu verkaufen."),
        "t1-microservices" => F(t, "Microservices sind unabhängig deploybare Dienste mit eigener Datenhoheit, kommunizierend über Netze.",
            "Nutzen: Skalierung, Teamautonomie. Kosten: Verteilung, Konsistenz, Betrieb. Nicht Standardlösung für Ausbildungsprojekte.",
            "Ticket-Service und Knowledge-Base-Service getrennt.",
            "Falle: Jede Klasse als Microservice."),
        "t1-event-driven" => F(t, "Event-driven Architecture reagiert auf Ereignisse (Topic/Queue), entkoppelt Erzeuger und Verbraucher.",
            "Choreographie vs. Orchestrierung. At-least-once vs. exactly-once Semantik beachten.",
            "TicketGeschlossen → Statistik-Service aktualisiert Kennzahlen.",
            "Falle: Events mit synchronen RPC-Calls gleichzusetzen."),
        "t1-mvc" => F(t, "MVC: Model (Daten/Fachlichkeit), View (Darstellung), Controller (Eingabe/Steuerung). In WPF oft MVVM (ViewModel statt Controller).",
            "Ziel: UI von Logik trennen, Testbarkeit. Observer/Binding aktualisiert die View.",
            "TicketModel, TicketView, TicketController bzw. TicketViewModel.",
            "Falle: Die gesamte Fachlogik in der View zu belassen und das MVC zu nennen."),
        "t1-muster" => F(t, "Entwurfsmuster sind bewährte, benannte Lösungen für wiederkehrende Entwurfsprobleme (GoF u. a.).",
            "Erzeugung, Struktur, Verhalten. Muster sind kein Selbstzweck.",
            "Observer für UI-Updates, Factory für Ticketarten, DI statt Service-Locator.",
            "Falle: Singleton überall 'weil globaler Zugriff praktisch ist'."),
        "t1-factory" => F(t, "Factory Method delegiert Objekterzeugung an Unterklassen oder spezialisierte Fabrikmethoden, statt new überall zu streuen.",
            "Erhöht Flexibilität bei Produktfamilien. Abstract Factory erzeugt zusammengehörige Produkte.",
            "TicketFactory.erzeuge(typ) → BugTicket oder ChangeTicket.",
            "Falle: Eine Methode mit new als vollständiges Factory-Method-Muster auszugeben, ohne die Variationsnaht."),
        "t1-observer" => F(t, "Observer: Subjekt benachrichtigt abhängige Beobachter über Änderungen, ohne sie konkret zu kennen.",
            "Publish/Subscribe, Events, INotifyPropertyChanged, Reactive. Achtung auf Lebenszyklus/Lecks.",
            "Ticket.StatusChanged → UI und Logger.",
            "Falle: Observer mit Polling in einer Endlosschleife zu verwechseln."),
        "t1-singleton" => F(t, "Singleton stellt sicher, dass eine Klasse genau eine Instanz hat und global darauf zugegriffen werden kann.",
            "In Tests und Parallelität problematisch. Heute oft durch DI mit Lebensdauer Singleton ersetzt. Thread-sichere Erzeugung beachten.",
            "Ein AppDbContext-Factory-Root, nicht zwingend GoF-Singleton.",
            "Falle: Singleton als einzig akzeptables Muster für Konfiguration, obwohl DI klarer ist."),
        "t1-di" => F(t, "Dependency Injection gibt Abhängigkeiten von außen (Konstruktor), statt sie intern zu erzeugen. Ermöglicht Austausch und Tests.",
            "IoC-Container registriert Interfaces. Lifetime: transient, scoped, singleton. Keine Service-Locator-Kaskade in der Fachlogik.",
            "Aufgabentrainer(IExerciseGenerator generator)",
            "Falle: new KonkreteAbhaengigkeit() in jeder View als DI zu bezeichnen."),
        "t1-lizenzen" => F(t, "Lizenzmodelle regeln Nutzungs-, Änderungs- und Weitergaberechte. Open Source vs. proprietär, Copyleft vs. permissive.",
            "Lizenzcompliance ist Projekt- und Prüfungsstoff (GPL in proprietärer Software).",
            "Bibliothek MIT → eigene App darf proprietär bleiben bei Namensnennung.",
            "Falle: 'Open Source bedeutet gemeinfrei / ohne Bedingungen'."),
        "t1-opensource" => F(t, "Open Source gewährt Quellzugang plus Nutzungsrechte nach Lizenz, nicht automatisch 'kostenlos ohne Pflichten'.",
            "Freiheiten: nutzen, verstehen, weitergeben, verbessern – mit Lizenzauflagen.",
            "Linux-Kernel unter GPL-2.0.",
            "Falle: Freeware mit Open Source gleichzusetzen."),
        "t1-proprietaer" => F(t, "Proprietäre Software behält Rechte beim Anbieter; Nutzung nur laut EULA, Quellcode meist geschlossen.",
            "Kauf/Miete/SaaS ändert das Urheberrecht nicht automatisch. Audit- und Cloud-Klauseln prüfen.",
            "Klassische Office-Lizenz ohne Weitergaberecht des Quellcodes.",
            "Falle: Kauf einer Lizenz als Eigentum am Code zu verstehen."),
        "t1-gpl-mit-apache" => F(t, "GPL: starkes Copyleft, Abgeleitete müssen GPL bleiben. LGPL: Copyleft primär auf die Bibliothek. MIT/BSD: permissiv, kurze Hinweispflicht. Apache 2.0: permissiv plus Patentklausel.",
            "GPL-Code in proprietärer geschlossener Distribution ist lizenzrechtlich kritisch. Apache 2.0 verlangt NOTICE-Erhalt.",
            "MIT-Bibliothek in Closed Source mit Copyright-Hinweis ist typisch zulässig.",
            "Falle: Alle OSS-Lizenzen als 'beliebig in Closed Source einbettbar' zu behandeln."),
        "t1-qs" => F(t, "Qualitätssicherung umfasst konstruktive (Reviews, Standards, Pairing) und analytische Maßnahmen (Tests, Analyse) über den Lebenszyklus.",
            "Testpyramide, DoD, CI. Qualität ist mehr als 'wenig Bugs'.",
            "Definition of Done verlangt Review, Unit Tests und aktualisierte Doku.",
            "Falle: QS erst nach Fertigstellung als einmaliger Testdurchgang."),
        "t1-code-review" => F(t, "Code Review ist eine systematische Prüfung durch andere Personen anhand von Kriterien (Korrektheit, Lesbarkeit, Sicherheit, Tests).",
            "Pull Request, Checklisten, Vier-Augen-Prinzip. Nicht persönlich, sondern am Artefakt.",
            "PR: SQL-Injection-Risiko in String-Konkatenation gefunden.",
            "Falle: Review als 'Linter ist grün, also fertig' ohne menschliches Lesen, wenn die Aufgabe Review verlangt."),
        "t1-static-analysis" => F(t, "Statische Analyse prüft Code ohne Ausführung: Compiler, Linter, SAST, Typprüfung.",
            "Findet z. B. unerreichbaren Code, einfache Taint-Flows. Ergänzt, ersetzt aber keine Tests.",
            "Analyser warnt vor unbenutzter Variable und SQL-Konkatenation.",
            "Falle: Statische Analyse mit Whitebox-Test (der ausgeführt wird) gleichzusetzen."),
        "t1-teststufen" => F(t, "Unit: isolierte Einheit. Integration: Zusammenspiel. System: System gegen Anforderungen. Abnahme: Auftraggeber gegen Lasten/Vertrag.",
            "V-Modell-Zuordnung. Testorakel und Testdaten gehören dazu.",
            "Unit: Preisberechnung. Integration: API+DB. Abnahme: Szenario 'Ticket eskalieren' mit Fachseite.",
            "Falle: Abnahmetest als Unit Test der GUI-Buttons ohne Fachkriterium."),
        "t1-cicd" => F(t, "Continuous Integration merget häufig und baut/testet automatisch. Continuous Delivery/Deployment liefert automatisch in Staging bzw. Produktion.",
            "Pipeline: Build, Test, Analyse, Artefakt, Deploy. Feature-Flags optional.",
            "Jeder Push auf main: restore, test, publish.",
            "Falle: CI ohne Tests als erfüllt zu betrachten."),
        "t1-pair" => F(t, "Pair Programming: zwei Personen an einer Aufgabe (Driver/Navigator), Wissenstransfer und frühe Fehlerfindung.",
            "Varianten: Strong-Style Pairing, Ensemble. Aufwand steigt, Nacharbeit kann sinken.",
            "Komplexe SQL-Migration zu zweit schreiben.",
            "Falle: Pairing als reines Zuschauen ohne Rotation."),
        "t1-dod" => F(t, "Die Definition of Done ist die gemeinsame Qualitätscheckliste, wann ein Increment fertig ist.",
            "Beispiel: Code gereviewt, Tests grün, Doku, keine offenen Sev-1, Accessibility-Check. Unterschied zu Acceptance Criteria einer Story.",
            "DoD: Unit Tests, Review, Changelog.",
            "Falle: DoD mit 'PO hat einmal genickt' ohne Qualitätskriterien gleichzusetzen."),
        _ => Teil2Or3(t)
    };
